package com.healthmd.accountsync

import com.healthmd.sharedsetup.SharedSetupV2Codec
import com.healthmd.sharedsetup.SharedSetupVersionedDecodeResult
import java.security.MessageDigest
import java.text.Normalizer
import java.util.Base64
import kotlinx.serialization.json.*

/** Proposed codec only. No auth, persistence, native apply or export effects. */
class ProfileSyncV1(private val sharedSetup: SharedSetupV2Codec = SharedSetupV2Codec()) {
    class Invalid(val category: String = "invalid") : IllegalArgumentException("profile_sync_$category")
    class Content private constructor(val contentJson: String, val hash: String, private val flags: List<String>) {
        val requiresAction: List<String> get() = flags.toList()
        companion object {
            internal fun validated(codec: ProfileSyncV1, bytes: ByteArray, expectedHash: String?): Content {
                val snapshot = bytes.copyOf()
                val root = obj(parseJson(snapshot, CONTENT_MAX))
                shape(root, portableSchema)
                val flags = codec.validateContent(root)
                val hash = contentHash(snapshot)
                need(expectedHash == null || expectedHash == hash, "hash")
                return Content(snapshot.decodeToString(throwOnInvalidSequence = true), hash, flags.sorted())
            }
        }
    }
    class Record private constructor(val profileId: String, val objectRevision: Long, val eventSequence: Long,
                                     val orderKey: Long?, val contentRevision: Long?, val content: Content?) {
        val deleted: Boolean get() = content == null
        companion object {
            internal fun validated(codec: ProfileSyncV1, bytes: ByteArray): Record {
                val root = obj(parseJson(bytes)); discriminate(root)
                exact(root, "schema schema_version profile_id object_revision event_sequence order_key deleted content_revision content_hash content_json")
                val id = opaque(root["profile_id"], "psp_")
                val revision = integer(root["object_revision"]); val sequence = integer(root["event_sequence"])
                if (bool(root["deleted"])) {
                    need(listOf("order_key", "content_revision", "content_hash", "content_json").all { root[it] == JsonNull })
                    return Record(id, revision, sequence, null, null, null)
                }
                val order = integer(root["order_key"], 0); val contentRevision = integer(root["content_revision"])
                need(contentRevision <= revision)
                val content = codec.parseContent(text(root["content_json"]).encodeToByteArray(), opaque(root["content_hash"], "", 64))
                return Record(id, revision, sequence, order, contentRevision, content)
            }
        }
    }
    class Mutation internal constructor(val operation: String, val mutationId: String, val baseRevision: Long,
                                       val profileId: String?, val orderKey: Long?, val content: Content?, val requestHash: String)
    class Page internal constructor(val mode: String, val snapshotId: String, val highWatermark: Long,
                                   private val records: List<Record>, val nextCursor: String?) {
        val items: List<Record> get() = records.toList()
    }
    // Immutable selectors only; parsing is not authenticated owner/cursor authority.
    sealed interface ReadRequest {
        enum class PageMode(val wireValue: String) { CHANGES("changes"), SNAPSHOT("snapshot") }
        class Page internal constructor(val mode: PageMode, val cursor: String?, val limit: Int) : ReadRequest
        class Revision internal constructor(val profileId: String, val contentRevision: Long, val contentHash: String) : ReadRequest
    }
    enum class ErrorResult(val wireValue: String) {
        UNAVAILABLE("unavailable"), INVALID("invalid"), REQUIRES_UPGRADE("requires_upgrade"), CONFLICT("conflict"),
        GONE("gone"), NOT_FOUND("not_found"), RESYNC_REQUIRED("resync_required"), IDEMPOTENCY_MISMATCH("idempotency_mismatch"),
        INTENT_EXPIRED("intent_expired"), VERIFICATION_PENDING("verification_pending"), QUOTA_EXCEEDED("quota_exceeded")
    }
    class FixedError internal constructor(val result: ErrorResult)
    fun parseContent(bytes: ByteArray, expectedHash: String? = null): Content = Content.validated(this, bytes, expectedHash)
    fun parseRecord(bytes: ByteArray): Record = Record.validated(this, bytes)
    fun parseMutation(bytes: ByteArray): Mutation {
        val snapshot = bytes.copyOf()
        val root = obj(parseJson(snapshot)); discriminate(root)
        val op = text(root["operation"]); need(op in listOf("create", "update", "reorder", "delete"))
        var fields = "schema schema_version operation mutation_id base_revision"
        if (op != "create") fields += " profile_id"
        if (op in listOf("create", "update")) fields += " content_json content_hash"
        if (op == "reorder") fields += " order_key"
        exact(root, fields)
        val id = opaque(root["mutation_id"], "psm_"); val base = integer(root["base_revision"], if (op == "create") 0 else 1)
        if (op == "create") need(base == 0L)
        val profile = if (op == "create") null else opaque(root["profile_id"], "psp_")
        val content = if (op in listOf("create", "update")) parseContent(text(root["content_json"]).encodeToByteArray(), opaque(root["content_hash"], "", 64)) else null
        return Mutation(op, id, base, profile, if (op == "reorder") integer(root["order_key"], 0) else null, content, mutationHash(snapshot))
    }
    fun parseRead(bytes: ByteArray): ReadRequest {
        val root = obj(parseJson(bytes, 8192)); discriminate(root)
        val mode = text(root["mode"])
        if (mode == "revision") {
            exact(root, "schema schema_version mode profile_id content_revision content_hash")
            return ReadRequest.Revision(opaque(root["profile_id"], "psp_"), integer(root["content_revision"]), opaque(root["content_hash"], "", 64))
        }
        val pageMode = ReadRequest.PageMode.entries.firstOrNull { it.wireValue == mode } ?: throw Invalid()
        exact(root, "schema schema_version mode cursor limit")
        val limit = integer(root["limit"]); need(limit <= 8)
        return ReadRequest.Page(pageMode, if (root["cursor"] == JsonNull) null else opaque(root["cursor"], "psc_", 64), limit.toInt())
    }
    // Fixed non-success only; no private reflection, cursor progression or retry effects.
    fun parseError(bytes: ByteArray): FixedError {
        val root = obj(parseJson(bytes, 8192)); discriminate(root); exact(root, "schema schema_version result")
        val result = ErrorResult.entries.firstOrNull { it.wireValue == text(root["result"]) } ?: throw Invalid()
        return FixedError(result)
    }
    fun parsePage(bytes: ByteArray): Page {
        val root = obj(parseJson(bytes)); discriminate(root)
        exact(root, "schema schema_version mode snapshot_id high_watermark items next_cursor complete")
        val mode = text(root["mode"]); need(mode in listOf("snapshot", "changes"))
        val id = opaque(root["snapshot_id"], "pss_"); val high = integer(root["high_watermark"], 0)
        val complete = bool(root["complete"]); need(complete == (root["next_cursor"] == JsonNull))
        val cursor = if (root["next_cursor"] == JsonNull) null else opaque(root["next_cursor"], "psc_", 64)
        val rows = arr(root["items"]); need(rows.size <= 8 && (complete || rows.isNotEmpty()))
        val records = rows.map { parseRecord(it.toString().encodeToByteArray()) }
        need(records.all { it.eventSequence <= high })
        if (mode == "snapshot") need(records.none { it.deleted } && records.map { it.profileId }.distinct().size == records.size)
        records.zipWithNext().forEach { (a, b) ->
            need(if (mode == "changes") a.eventSequence < b.eventSequence else
                a.orderKey!! < b.orderKey!! || (a.orderKey == b.orderKey && a.profileId < b.profileId))
        }
        return Page(mode, id, high, records, cursor)
    }
    private fun validateContent(root: JsonObject): List<String> {
        val profile = obj(root["profile"])
        val name = text(profile["name"])
        need(name.isNotEmpty() && name.first().code !in nameEdgeWhitespace && name.last().code !in nameEdgeWhitespace)
        need(name.none { it.code < 32 || it.code == 127 || it.code in nameLineBreaks })
        val witness = JsonObject(mapOf(
            "schema" to JsonPrimitive("healthmd.shared_setup"), "schema_version" to JsonPrimitive(2),
            "created_by" to JsonObject(mapOf("platform" to root.getValue("origin_platform"), "app_version" to JsonPrimitive("profile-sync-v1-witness"))),
            "metric_registry" to root.getValue("metric_registry"), "metric_aliases" to root.getValue("metric_aliases"),
            "profiles" to JsonArray(listOf(JsonObject(profile + ("bundle_id" to JsonPrimitive("profile-001"))))),
            "active_profile" to JsonPrimitive("profile-001"),
        ))
        // Actual shipped v2 typed decode and semantic/security validation, not a success oracle.
        need(sharedSetup.decode(witness.toString().encodeToByteArray()) is SharedSetupVersionedDecodeResult.Valid, "v2")
        val ext = obj(profile["platform_extensions"])
        if (ext["apple"] != JsonNull) {
            val apple = obj(ext["apple"])["schedule"]!!
            need((apple == JsonNull) == (profile["schedule"] == JsonNull))
            if (apple != JsonNull) {
                val a = obj(apple); val c = obj(obj(profile["schedule"])["cadence"])
                val f = text(a["frequency"]); val unit = text(c["unit"])
                need((f == "daily" && integer(c["value"]) == 1L && unit == "days") ||
                    (f == "weekly" && integer(c["value"]) == 1L && unit == "weeks") ||
                    (f == "custom" && unit == text(a["custom_unit"])))
            }
        }
        if (profile["schedule"] != JsonNull) need(text(obj(obj(profile["schedule"])["cadence"])["anchor_date"]).take(4).toInt() >= 1)
        val dest = obj(profile["destination"])
        if (dest["api_endpoint"] != JsonNull) need(!Regex("[@%?#\\\\]").containsMatchIn(text(obj(dest["api_endpoint"])["path"])))
        val matchesRegistry = text(obj(root["metric_registry"])["registry_sha256"]) == text(pinnedRegistry["sha256"])
        if (matchesRegistry) arr(root["metric_aliases"]).forEach { row ->
            val alias = obj(row); val binding = arr(obj(pinnedRegistry["aliases"])[text(alias["semantic_id"])])
            need(alias["equivalence"] == binding[0] && alias["apple_selection_id"] == binding[1] && alias["android_selection_id"] == binding[2], "registry")
        }
        security(root, emptyList())
        val flags = mutableListOf("unbound_destination", "local_review_required", "platform_review")
        if (!matchesRegistry) flags += "registry_review"
        if (profile["schedule"] != JsonNull) flags += "schedule_disabled"
        if (text(obj(obj(profile["presentation"])["markdown"])["style"]) == "custom") flags += "template_review"
        return flags
    }
    companion object {
        const val CONTENT_MAX = 262_144
        const val WIRE_MAX = 4_194_304
        const val SAFE_MAX = 9_007_199_254_740_991L
        // All finite edge-policy points are BMP. No platform trim() or name rewrite.
        private val nameEdgeWhitespace = setOf(0x0009, 0x000A, 0x000B, 0x000C, 0x000D, 0x0020, 0x0085, 0x00A0, 0x1680,
            0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF)
        private val nameLineBreaks = setOf(0x0085, 0x2028, 0x2029)
        private val json = Json { isLenient = false }
        private fun need(ok: Boolean, category: String = "invalid") { if (!ok) throw Invalid(category) }
        private fun obj(v: JsonElement?): JsonObject = v as? JsonObject ?: throw Invalid()
        private fun arr(v: JsonElement?): JsonArray = v as? JsonArray ?: throw Invalid()
        private fun text(v: JsonElement?): String {
            val p = v as? JsonPrimitive ?: throw Invalid(); need(p.isString); return p.content
        }
        private fun bool(v: JsonElement?): Boolean {
            val p = v as? JsonPrimitive ?: throw Invalid(); need(!p.isString && p.content in listOf("true", "false")); return p.content == "true"
        }
        private fun integer(v: JsonElement?, minimum: Long = 1): Long {
            val p = v as? JsonPrimitive ?: throw Invalid("integer")
            val n = if (!p.isString && Regex("-?(?:0|[1-9][0-9]*)").matches(p.content)) p.content.toLongOrNull() else null
            need(n != null && n in minimum..SAFE_MAX && p.content != "-0", "integer"); return n!!
        }
        private fun opaque(v: JsonElement?, prefix: String, length: Int = 32): String {
            val s = text(v); need(Regex("^$prefix[0-9a-f]{$length}$").matches(s)); return s
        }
        private fun exact(o: JsonObject, fields: String) { need(o.keys == fields.split(' ').toSet()) }
        private fun discriminate(o: JsonObject) { need(text(o["schema"]) == "healthmd.profile_sync"); need(integer(o["schema_version"]) == 1L, "version") }
        fun contentHash(bytes: ByteArray): String = hashExactBytes(bytes, "healthmd.profile_sync.portable/v1\u0000")
        fun mutationHash(bytes: ByteArray): String = hashExactBytes(bytes, "healthmd.profile_sync.mutate/v1\u0000")
        private fun hashExactBytes(bytes: ByteArray, domain: String): String {
            val digest = MessageDigest.getInstance("SHA-256")
            digest.update(domain.encodeToByteArray())
            return digest.digest(bytes).joinToString("") { "%02x".format(it.toInt() and 255) }
        }
        fun parseJson(bytes: ByteArray, maximum: Int = WIRE_MAX): JsonElement {
            need(bytes.size <= maximum, "size")
            val s = try { bytes.decodeToString(throwOnInvalidSequence = true) } catch (_: Exception) { throw Invalid("utf8") }
            val parser = Parser(s, if (maximum == CONTENT_MAX) 65_536 else WIRE_MAX)
            val result = parser.value(0); parser.space(); need(parser.pos == s.length, "json"); return result
        }
        private class Parser(val s: String, val maxString: Int) {
            var pos = 0; var nodes = 0
            fun space() { while (s.getOrNull(pos) in listOf(' ', '\t', '\r', '\n')) pos++ }
            fun consume(c: Char) { need(s.getOrNull(pos) == c, "json"); pos++ }
            fun string(): JsonPrimitive {
                val start = pos; consume('"'); var escaped = false
                while (pos < s.length) {
                    val c = s[pos++]
                    if (!escaped && c == '"') {
                        val v = try { json.parseToJsonElement(s.substring(start, pos)) as JsonPrimitive } catch (_: Exception) { throw Invalid("json") }
                        val t = v.content; var i = 0
                        while (i < t.length) {
                            val ch = t[i++]
                            if (ch.isHighSurrogate()) { need(i < t.length && t[i++].isLowSurrogate(), "unicode") }
                            else need(!ch.isLowSurrogate(), "unicode")
                        }
                        need(t.codePointCount(0, t.length) <= maxString, "string"); return v
                    }
                    escaped = !escaped && c == '\\'
                }
                throw Invalid("json")
            }
            fun value(depth: Int): JsonElement {
                need(depth <= 20, "depth"); need(++nodes <= 16_384, "nodes"); space()
                val c = s.getOrNull(pos)
                if (c == '"') return string()
                if (c == '{' || c == '[') {
                    pos++; space(); val end = if (c == '{') '}' else ']'
                    val map = linkedMapOf<String, JsonElement>(); val array = mutableListOf<JsonElement>(); val keys = mutableSetOf<String>(); var count = 0
                    if (s.getOrNull(pos) == end) { pos++; return if (c == '{') JsonObject(map) else JsonArray(array) }
                    while (true) {
                        need(++count <= 512, "container"); space()
                        if (c == '{') {
                            val key = string().content; need(key.codePointCount(0, key.length) <= 65_536, "string")
                            need(keys.add(Normalizer.normalize(key, Normalizer.Form.NFC)), "duplicate_key")
                            space(); consume(':'); map[key] = value(depth + 1)
                        } else array += value(depth + 1)
                        space(); if (s.getOrNull(pos) == end) { pos++; return if (c == '{') JsonObject(map) else JsonArray(array) }; consume(',')
                    }
                }
                for ((token, result) in listOf("null" to JsonNull, "true" to JsonPrimitive(true), "false" to JsonPrimitive(false))) {
                    if (s.startsWith(token, pos)) { pos += token.length; return result }
                }
                val token = Regex("-?(?:0|[1-9][0-9]*)").find(s, pos)?.takeIf { it.range.first == pos }?.value ?: throw Invalid("json")
                pos += token.length; need(s.getOrNull(pos) !in ".eE0123456789".toList(), "integer")
                val n = token.toLongOrNull(); need(token != "-0" && n != null && n in -SAFE_MAX..SAFE_MAX, "integer")
                return JsonPrimitive(n!!)
            }
        }
        private fun shape(v: JsonElement, c: JsonObject) {
            c["\$ref"]?.let { ref ->
                val name = text(ref); need(name.startsWith("#/\$defs/")); shape(v, obj(obj(portableSchema["\$defs"])[name.substring(8)])); return
            }
            c["oneOf"]?.let { branches ->
                val branch = arr(branches).firstOrNull { (obj(it)["type"] == JsonPrimitive("null")) == (v == JsonNull) } ?: throw Invalid()
                shape(v, obj(branch)); return
            }
            c["const"]?.let { need(v == it, "shape") }
            c["enum"]?.let { need(v in arr(it), "shape") }
            when (c["type"]?.let(::text)) {
                "null" -> need(v == JsonNull)
                "boolean" -> bool(v)
                "integer" -> need(integer(v, c["minimum"]?.jsonPrimitive?.long ?: -SAFE_MAX) <= (c["maximum"]?.jsonPrimitive?.long ?: SAFE_MAX))
                "string" -> {
                    val s = text(v); val size = s.codePointCount(0, s.length)
                    need(size >= (c["minLength"]?.jsonPrimitive?.int ?: 0) && size <= (c["maxLength"]?.jsonPrimitive?.int ?: 65_536))
                    c["pattern"]?.let { need(Regex(text(it)).containsMatchIn(s), "shape") }
                }
                "object" -> {
                    val o = obj(v); val properties = c["properties"]?.let(::obj) ?: JsonObject(emptyMap())
                    need(c["required"]?.let { arr(it).all { key -> text(key) in o } } != false)
                    need(o.size <= (c["maxProperties"]?.jsonPrimitive?.int ?: 512))
                    o.forEach { (key, child) ->
                        c["propertyNames"]?.let { shape(JsonPrimitive(key), obj(it)) }
                        val candidate = properties[key] ?: c["additionalProperties"]
                        shape(child, obj(candidate)) // false/missing cannot accept unknown fields
                    }
                }
                "array" -> {
                    val a = arr(v); need(a.size >= (c["minItems"]?.jsonPrimitive?.int ?: 0) && a.size <= (c["maxItems"]?.jsonPrimitive?.int ?: 512))
                    if (c["uniqueItems"] == JsonPrimitive(true)) need(a.distinct().size == a.size)
                    a.forEach { shape(it, obj(c["items"])) }
                }
            }
        }
        private fun security(v: JsonElement, path: List<String>, endpoint: Boolean = false) {
            when (v) {
                is JsonObject -> v.forEach { (key, child) ->
                    val k = key.replace(Regex("([a-z0-9])([A-Z])"), "$1_$2").lowercase().replace(Regex("[^a-z0-9]+"), "_").trim('_')
                    val endpointParent = path.takeLast(2) == listOf("destination", "api_endpoint")
                    val markdownParent = path.takeLast(2) == listOf("presentation", "markdown")
                    val safe = (k == "credentials_required" && endpointParent) || (k == "header_level" && markdownParent)
                    val rawAllowed = k == "raw_snapshot" && path.takeLast(3) == listOf("platform_extensions", "android", "export")
                    need((k != "raw_snapshot" || rawAllowed) && !(k == "enabled" && "schedule" in path) &&
                        !Regex("(_timestamp|_millis|_at)$").containsMatchIn(k) &&
                        (safe || (k !in forbiddenExact && forbiddenFragments.none(k::contains))), "prohibited")
                    security(child, path + k, endpointParent && key in listOf("host", "path") && v["scheme"] == JsonPrimitive("https"))
                }
                is JsonArray -> v.forEach { security(it, path + "[]") }
                is JsonPrimitive -> if (v.isString) {
                    val s = v.content
                    need(!Regex("(?i)(content|file|saf)://|authorization:|\\b(?:bearer|basic)\\s+[a-z0-9+/=_-]|-----begin private key|https?://[^\\s/@]+(?::[^\\s/@]*)?@|[?&](?:access_?token|api_?key|password|secret|authorization)=").containsMatchIn(s), "prohibited")
                    if (!endpoint) need(!Regex("(?i)(?<![0-9a-f])[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}(?![0-9a-f])|(?:^|[\\s\"'])(?:[a-z]:[\\\\/])|/(users|home|private|var/mobile|data/user|storage/emulated|sdcard|mnt)/|^~/").containsMatchIn(s), "prohibited")
                }
            }
        }
        // BEGIN GENERATED PINNED DATA (build_source_artifacts.py --embed)
        private val DATA_BASE64 = listOf(
            "",
            "",
            "",
            ""
        ).joinToString("")



        // END GENERATED PINNED DATA
        private val pinnedData = json.parseToJsonElement(Base64.getDecoder().decode(DATA_BASE64).decodeToString()).jsonObject
        private val portableSchema = pinnedData.getValue("shape").jsonObject
        private val pinnedRegistry = pinnedData.getValue("registry").jsonObject
        private val forbiddenExact = pinnedData.getValue("forbidden_exact").jsonArray.map { it.jsonPrimitive.content }.toSet()
        private val forbiddenFragments = pinnedData.getValue("forbidden_fragments").jsonArray.map { it.jsonPrimitive.content }
    }
}
